from abc import ABC, abstractmethod
from pathlib import Path
from typing import Any

import anyio
from pydantic import BaseModel, ConfigDict, Field

INVALID_FILENAME_ERROR_MESSAGE = 'Error: Invalid filename format. Must be alphanumeric with a supported extension.'
DEFAULT_FILE_SYSTEM_PATH = 'browseruse_agent_data'


class FileSystemError(Exception):
	"""Custom exception for file system operations that should be shown to LLM"""

	pass


class BaseFile(BaseModel, ABC):
	"""Base class for all file types"""

	model_config = ConfigDict(arbitrary_types_allowed=True)

	name: str
	content: str = ''

	# --- Subclasses must implement these ---
	@property
	@abstractmethod
	def extension(self) -> str:
		"""Return the file extension (without leading dot)"""
		pass

	def display_content(self) -> str:
		"""Return content formatted for the describe function"""
		return self.content

	# --- In-memory content operations (shared by all file types) ---
	def update_content(self, new_content: str) -> None:
		"""Replace the in-memory content of the file"""
		self.content = new_content

	def append_content(self, content: str) -> None:
		"""Append to the in-memory content of the file"""
		self.content += content

	def read(self) -> str:
		"""Return the raw in-memory content"""
		return self.content

	# --- Disk synchronization ---
	def sync_to_disk_sync(self, base_dir: Path) -> None:
		"""Synchronously write the in-memory content to disk"""
		file_path = base_dir / self.full_name
		try:
			file_path.write_text(self.content)
		except Exception as e:
			raise FileSystemError(f"Error: Could not write file '{self.full_name}' to disk. {str(e)}")

	async def sync_to_disk(self, base_dir: Path) -> None:
		"""Asynchronously write the in-memory content to disk"""
		file_path = base_dir / self.full_name
		try:
			async with await anyio.open_file(file_path, 'w') as f:
				await f.write(self.content)
		except Exception as e:
			raise FileSystemError(f"Error: Could not write file '{self.full_name}' to disk. {str(e)}")

	async def write(self, content: str, base_dir: Path) -> None:
		"""Replace content in memory and sync to disk"""
		self.update_content(content)
		await self.sync_to_disk(base_dir)

	async def append(self, content: str, base_dir: Path) -> None:
		"""Append content in memory and sync to disk"""
		self.append_content(content)
		await self.sync_to_disk(base_dir)

	# --- Metadata ---
	@property
	def get_size(self) -> int:
		"""Get file size in characters"""
		return len(self.content)

	@property
	def get_line_count(self) -> int:
		"""Get number of lines in file"""
		return len(self.content.split('\n'))

	@property
	def full_name(self) -> str:
		"""Get full filename with extension"""
		return f'{self.name}.{self.extension}'


